<?php declare(strict_types=1); ?>
<div class="mod-wrap"><p><a href="<?= $v->url($v->app->boards->postPath($post)) ?>">View post /<?= $v::e($post['slug']) ?>/<?= $v::e($post['id']) ?></a></p><?= $v->post($post, true) ?><div class="clear"></div>
<?php if ($role->allows('edit')): ?><form method="post" action="<?= $v->url('mod.php') ?>"><?= $v->csrf() ?><input type="hidden" name="id" value="<?= $v::e($post['id']) ?>"><input type="hidden" name="action" value="edit"><fieldset><legend>Edit post</legend><label>Name <input name="name" maxlength="50" value="<?= $v::e($post['name']) ?>"></label><label>Subject <input name="subject" maxlength="120" value="<?= $v::e($post['subject']) ?>"></label><label>Comment <textarea name="body" rows="10" maxlength="30000"><?= $v::e($post['body']) ?></textarea></label><button>Save changes</button></fieldset></form><?php endif ?>
<?php if ($post['thread_id'] === null): ?><?php foreach (['sticky' => $post['sticky'] ? 'Unsticky thread' : 'Sticky thread', 'lock' => $post['locked'] ? 'Unlock thread' : 'Lock thread'] as $action => $label): ?><?php if ($role->allows($action)): ?><form class="inline-form" method="post" action="<?= $v->url('mod.php') ?>"><?= $v->csrf() ?><input type="hidden" name="id" value="<?= $v::e($post['id']) ?>"><button name="action" value="<?= $v::e($action) ?>"><?= $v::e($label) ?></button></form><?php endif ?><?php endforeach ?><?php endif ?>
<form method="post" action="<?= $v->url('mod.php') ?>"><?= $v->csrf() ?><input type="hidden" name="id" value="<?= $v::e($post['id']) ?>"><fieldset><legend>Delete</legend><p>Deleting an opening post also removes its replies and attachments.</p><label>Type <?= $v::e($post['id']) ?> to confirm <input name="confirm" inputmode="numeric" maxlength="10" required></label><button name="action" value="files">Delete files only</button> <button name="action" value="delete">Delete post</button></fieldset></form></div>
